from pathlib import Path

p = Path('/home/ubuntu/do-nhay-ff-sua/client/src/pages/Home.tsx')
s = p.read_text()

# Add ref for latest analysis and a neutral fallback generator.
insert_after = 'function generateSensitivity(device: Device, profile: string, fps: number, weapon: string, dpi: number): Sensitivity {\n'
if 'function createFallbackDevice' not in s:
    fallback = '''function createFallbackDevice(query: string): Device {\n  const clean = query.trim().replace(/\\s+/g, " ");\n  const [brand = "Unknown", ...rest] = clean.split(" ");\n  return { id: `generated-${normalize(clean)}`, brand, model: rest.join(" ") || clean, aliases: [], type: "PHONE", tier: "MIDRANGE", refreshRate: 90, touchSampling: 180, ram: 8, processorLevel: 6, os: "Android", score: 62, gradient: "from-slate-400/20 to-cyan-500/5", accent: "#9ab7bd" };\n}\n\n'''
    s = s.replace(insert_after, fallback + insert_after)

# Replace profile bootstrap with explicit opt-in persisted profile only.
start = s.index('const savedProfile = (() => {')
end = s.index('\n\nexport default function Home()', start)
profile_block = '''const savedProfile = (() => {\n  if (typeof window === "undefined" || localStorage.getItem("sua-profile-committed") !== "1") return null;\n  try { return JSON.parse(localStorage.getItem("sua-profile") || "null") as { deviceId?: string; profile?: string; fps?: number; dpi?: number } | null; } catch { return null; }\n})();'''
s = s[:start] + profile_block + s[end:]

# Neutral initial state, and independent profile device.
s = s.replace('const [selectedDevice, setSelectedDevice] = useState<Device>(() => devices.find((device) => device.id === savedProfile?.deviceId) || devices[0]);', 'const [selectedDevice, setSelectedDevice] = useState<Device | null>(null);\n  const [profileDevice, setProfileDevice] = useState<Device | null>(() => devices.find((device) => device.id === savedProfile?.deviceId) || null);')
s = s.replace('const [result, setResult] = useState<Sensitivity>(() => generateSensitivity(devices[0], "Kéo tâm", 144, "M1887", 470));', 'const [result, setResult] = useState<Sensitivity | null>(null);')
s = s.replace('  const searchRef = useRef<HTMLInputElement>(null);', '  const searchRef = useRef<HTMLInputElement>(null);\n  const latestRequestId = useRef(0);')
s = s.replace('  useEffect(() => { localStorage.setItem("sua-profile", JSON.stringify({ deviceId: selectedDevice.id, profile, fps, dpi })); }, [selectedDevice.id, profile, fps, dpi]);\n  useEffect(() => { setResult(generateSensitivity(selectedDevice, profile, fps, weapon, dpi)); }, []);', '  useEffect(() => { if (profileDevice) { localStorage.setItem("sua-profile", JSON.stringify({ deviceId: profileDevice.id, profile, fps, dpi })); } }, [profileDevice, profile, fps, dpi]);')

# Replace handlers block.
old = '''  const selectDevice = (device: Device) => { setSelectedDevice(device); setQuery(`${device.brand} ${device.model}`); setSuggestionsOpen(false); };\n  const analyze = (device = selectedDevice) => {\n    setLoading(true); setSuggestionsOpen(false); setActiveSection("home");\n    window.setTimeout(() => { const next = generateSensitivity(device, profile, fps, weapon, dpi); setResult(next); setLoading(false); setHistory((old) => [device.model, ...old.filter((item) => item !== device.model)].slice(0, 5)); document.getElementById("result")?.scrollIntoView({ behavior: "smooth", block: "start" }); toast.success(`Đã phân tích cấu hình cho ${device.brand} ${device.model}`); }, 760);\n  };\n  const updateSensitivity = (key: keyof Sensitivity, value: number) => { setPreviousResult(result); setResult((old) => ({ ...old, [key]: value })); };\n  const updateChoice = (type: "profile" | "fps" | "weapon" | "dpi", value: string | number) => { if (type === "profile") setProfile(String(value)); if (type === "fps") setFps(Number(value)); if (type === "weapon") setWeapon(String(value)); if (type === "dpi") setDpi(Number(value)); window.setTimeout(() => setResult(generateSensitivity(selectedDevice, type === "profile" ? String(value) : profile, type === "fps" ? Number(value) : fps, type === "weapon" ? String(value) : weapon, type === "dpi" ? Number(value) : dpi)), 0); };\n  const copyResult = async () => { const text = `${selectedDevice.brand} ${selectedDevice.model}\\nĐộ nhạy FF SÚA\\n${sensitivityLabels.map(([key, label]) => `${label}: ${result[key]}`).join("\\n")}\\nDPI: ${result.dpi}`; await navigator.clipboard?.writeText(text); toast.success("Đã copy cấu hình độ nhạy"); };\n  const toggleFavorite = () => { setFavorites((old) => old.includes(selectedDevice.id) ? old.filter((item) => item !== selectedDevice.id) : [...old, selectedDevice.id]); toast.success(favorites.includes(selectedDevice.id) ? "Đã bỏ khỏi yêu thích" : "Đã lưu vào yêu thích"); };\n  const share = async () => { const shareText = `Độ nhạy FF SÚA — ${selectedDevice.brand} ${selectedDevice.model}`; if (navigator.share) await navigator.share({ title: "Độ Nhạy FF SÚA", text: shareText }); else { await navigator.clipboard?.writeText(shareText); toast.success("Đã copy nội dung chia sẻ"); } };'''
new = '''  const selectDevice = (device: Device) => { setSelectedDevice(device); setQuery(`${device.brand} ${device.model}`); setSuggestionsOpen(false); };\n  const analyze = (device?: Device) => {\n    if (!device) { toast.info("Nhập tên thiết bị để bắt đầu"); return; }\n    const requestId = ++latestRequestId.current;\n    setSelectedDevice(device);\n    setResult(null);\n    setLoading(true); setSuggestionsOpen(false); setActiveSection("home");\n    window.setTimeout(() => {\n      if (requestId !== latestRequestId.current) return;\n      const next = generateSensitivity(device, profile, fps, weapon, dpi);\n      setResult(next); setProfileDevice(device);\n      localStorage.setItem("sua-profile-committed", "1");\n      setLoading(false); setHistory((old) => [device.model, ...old.filter((item) => item !== device.model)].slice(0, 5));\n      document.getElementById("result")?.scrollIntoView({ behavior: "smooth", block: "start" });\n      toast.success(`Đã phân tích cấu hình cho ${device.brand} ${device.model}`);\n    }, 760);\n  };\n  const updateSensitivity = (key: keyof Sensitivity, value: number) => { if (!result) return; setPreviousResult(result); setResult((old) => old ? ({ ...old, [key]: value }) : old); };\n  const updateChoice = (type: "profile" | "fps" | "weapon" | "dpi", value: string | number) => {\n    if (!selectedDevice || !result) return;\n    if (type === "profile") setProfile(String(value)); if (type === "fps") setFps(Number(value)); if (type === "weapon") setWeapon(String(value)); if (type === "dpi") setDpi(Number(value));\n    setResult(generateSensitivity(selectedDevice, type === "profile" ? String(value) : profile, type === "fps" ? Number(value) : fps, type === "weapon" ? String(value) : weapon, type === "dpi" ? Number(value) : dpi));\n  };\n  const clearSearch = () => { ++latestRequestId.current; setQuery(""); setDebouncedQuery(""); setSuggestionsOpen(false); setSelectedDevice(null); setResult(null); setPreviousResult(null); setLoading(false); };\n  const copyResult = async () => { if (!selectedDevice || !result) return; const text = `${selectedDevice.brand} ${selectedDevice.model}\\nĐộ nhạy FF SÚA\\n${sensitivityLabels.map(([key, label]) => `${label}: ${result[key]}`).join("\\n")}\\nDPI: ${result.dpi}`; await navigator.clipboard?.writeText(text); toast.success("Đã copy cấu hình độ nhạy"); };\n  const toggleFavorite = () => { if (!selectedDevice) return; setFavorites((old) => old.includes(selectedDevice.id) ? old.filter((item) => item !== selectedDevice.id) : [...old, selectedDevice.id]); toast.success(favorites.includes(selectedDevice.id) ? "Đã bỏ khỏi yêu thích" : "Đã lưu vào yêu thích"); };\n  const share = async () => { if (!selectedDevice) return; const shareText = `Độ nhạy FF SÚA — ${selectedDevice.brand} ${selectedDevice.model}`; if (navigator.share) await navigator.share({ title: "Độ Nhạy FF SÚA", text: shareText }); else { await navigator.clipboard?.writeText(shareText); toast.success("Đã copy nội dung chia sẻ"); } };'''
if old not in s:
    raise SystemExit('handler block not found')
s = s.replace(old, new)

# Auto analyze should use a matched device, generated unknown device, or no-op; never stale selected default.
s = s.replace('const target = matches[0]?.device || selectedDevice; if (query && !matches.length) { analyze(selectedDevice); } else analyze(target);', 'const target = matches[0]?.device || (query.trim() ? createFallbackDevice(query) : undefined); analyze(target);')
s = s.replace('onClick={() => { setQuery(""); setSuggestionsOpen(false); }}', 'onClick={clearSearch}')

# Replace result section with conditional rendering, preserving loading state only after an actual analysis.
start = s.index('      <section className="container section-block split-section" id="result">')
end = s.index('\n\n      <section className="container profile-strip"', start)
result_section = '''      {(loading || (selectedDevice && result)) && <section className="container section-block split-section" id="result"><div className="section-heading result-heading"><div><p className="eyebrow"><span className="eyebrow-line" /> ANALYSIS OUTPUT / LIVE</p><h2>Độ nhạy FF đề xuất</h2></div><div className="result-actions"><button className="small-icon-button" onClick={() => analyze(selectedDevice || undefined)} title="Phân tích lại"><RotateCcw size={15} /></button><button className={`favorite-button ${selectedDevice && favorites.includes(selectedDevice.id) ? "is-favorite" : ""}`} onClick={toggleFavorite}><Heart size={15} fill={selectedDevice && favorites.includes(selectedDevice.id) ? "currentColor" : "none"} /> {selectedDevice && favorites.includes(selectedDevice.id) ? "ĐÃ LƯU" : "LƯU"}</button></div></div><div className="result-layout"><div className="result-card">{loading ? <div className="analysis-loading"><div className="scan-ring"><Crosshair size={29} /></div><div><p className="eyebrow">PHÂN TÍCH ĐỘ NHẠY FF</p><h3>Đang phân tích {selectedDevice?.brand} {selectedDevice?.model}...</h3><div className="loading-bar"><span /></div><small>Nhận diện thiết bị · kiểm tra database · tính DPI</small></div></div> : selectedDevice && result ? <><div className="result-device"><div className="result-device-icon"><MonitorSmartphone size={22} /></div><div><span className="eyebrow">DEVICE MATCH / {selectedDevice.type}</span><h3>{selectedDevice.brand} {selectedDevice.model}</h3><div className="result-tags"><span>{selectedDevice.tier}</span><span>{selectedDevice.refreshRate}Hz</span><span>{selectedDevice.os}</span><span className="verified"><ShieldCheck size={12} /> {selectedDevice.score >= 90 ? "VERIFIED DATA" : "ESTIMATED DATA"}</span></div></div><div className="match-score"><strong>{selectedDevice.score}%</strong><span>algorithm fit</span></div></div><div className="confidence-block"><div className="confidence-copy"><span>ĐỘ TIN CẬY DỮ LIỆU</span><strong>{selectedDevice.score}%</strong></div><div className="confidence-track"><span style={{ width: `${selectedDevice.score}%` }} /></div><small><CheckCircle2 size={13} /> {selectedDevice.score >= 90 ? "Thông số thiết bị đã biết" : "Thông số ước lượng — nên tinh chỉnh thêm"}</small></div><div className="sensitivity-list">{sensitivityLabels.map(([key, label]) => <div className="sensitivity-row" key={key}><span>{label}</span><div className="sensitivity-control"><div className="sensitivity-track"><span style={{ width: `${result[key] / 2}%` }} /></div><input className="sensitivity-range" aria-label={`Chỉnh ${label}`} type="range" min="0" max="200" value={result[key]} onChange={(event) => updateSensitivity(key, Number(event.target.value))} /></div><strong>{result[key]}</strong></div>)}</div><div className="result-footer"><span><Activity size={15} /> ENGINE PRESET: {profile.toUpperCase()}</span><span>UPDATED JUST NOW</span></div></> : null}</div>{selectedDevice && result && <aside className="control-panel"><div className="panel-header"><div><span className="eyebrow">FINE TUNING</span><h3>Chỉnh cấu hình</h3></div><SlidersHorizontal size={18} /></div><div className="control-group"><label>PROFILE</label><div className="pill-grid">{profiles.map((item) => <Pill key={item} active={profile === item} onClick={() => updateChoice("profile", item)}>{item}</Pill>)}</div></div><div className="control-group"><label>FPS TARGET</label><div className="pill-grid fps-grid">{fpsOptions.map((item) => <Pill key={item} active={fps === item} onClick={() => updateChoice("fps", item)}>{item}</Pill>)}</div></div><div className="control-group"><label>VŨ KHÍ ƯU TIÊN</label><div className="select-wrap"><select value={weapon} onChange={(event) => updateChoice("weapon", event.target.value)}>{weapons.map((item) => <option key={item}>{item}</option>)}</select><ChevronDown size={16} /></div></div><div className="control-group"><div className="label-row"><label>DPI <span className="label-value">{dpi}</span></label><span className="range-caption">420 — 560</span></div><input className="range-input" type="range" min="420" max="560" step="10" value={dpi} onChange={(event) => updateChoice("dpi", Number(event.target.value))} /></div><div className="panel-actions"><button className="primary-action" onClick={copyResult}><Copy size={15} /> COPY CONFIG</button><button className="secondary-action" onClick={share}>CHIA SẺ</button></div></aside>}</div></section>}'''
s = s[:start] + result_section + s[end:]

# Profile must be independent and empty until an intentional analysis was done.
old_profile_start = '      <section className="container profile-strip" id="profile-summary">'
ps = s.index(old_profile_start)
pe = s.index('\n\n      <section className="container compare-section"', ps)
profile_section = '''      <section className="container profile-strip" id="profile-summary"><div className="profile-intro"><div className="profile-avatar">S</div><div><p className="eyebrow"><span className="eyebrow-line" /> CẤU HÌNH CỦA TÔI</p><h2>Hồ sơ SÚA</h2><p>{profileDevice ? "Reload web vẫn giữ thiết bị và preset bạn đang dùng." : "Phân tích một thiết bị để bắt đầu hồ sơ của bạn."}</p></div></div><div className="profile-stat"><span>THIẾT BỊ HIỆN TẠI</span><strong>{profileDevice ? `${profileDevice.brand} ${profileDevice.model}` : "Chưa chọn"}</strong><small>{profileDevice ? `${profileDevice.tier} · ${profileDevice.refreshRate}Hz` : "Đang chờ phân tích"}</small></div><div className="profile-stat"><span>CẤU HÌNH ĐANG DÙNG</span><strong>{profileDevice ? profile : "Chưa có"}</strong><small>{profileDevice ? `${fps} FPS · DPI ${dpi}` : "—"}</small></div><div className="profile-stat"><span>CẤU HÌNH ĐÃ LƯU</span><strong>{favorites.length}</strong><small>{history.length} lần tìm gần nhất</small></div></section>'''
s = s[:ps] + profile_section + s[pe:]

# Compare section should only exist after a search result.
cs = s.index('      <section className="container compare-section"')
ce = s.index('\n\n      <section className="container lower-grid"', cs)
compare = s[cs:ce]
s = s[:cs] + '{selectedDevice && result && (\n' + compare + '\n      )}' + s[ce:]

p.write_text(s)
